package ompviewer

import (
	"testing"
)

func TestStatusPrefixMirrorsPythonContract(t *testing.T) {
	// tools/tool_status.py OMP_LANE_VIEWER_STATUS_PREFIX — the
	// producer/consumer contract prefix adapters recognize.
	if StatusPrefix != "OMP Lane: " {
		t.Fatalf("StatusPrefix = %q, want %q", StatusPrefix, "OMP Lane: ")
	}
}

func TestWatchURLQuotesLikePython(t *testing.T) {
	// Vectors generated by Python's urllib.parse.quote(selector, safe="/").
	vectors := []struct{ selector, quoted string }{
		{"/srv/work/proj/.hermes-lane/m", "/srv/work/proj/.hermes-lane/m"},
		{"/w/proj with space/x", "/w/proj%20with%20space/x"},
		{"/w/a+b/~x", "/w/a%2Bb/~x"},
		{"/w/100%/x", "/w/100%25/x"},
		{"/w/café/x", "/w/caf%C3%A9/x"},
		{"/w/a?b#c/x", "/w/a%3Fb%23c/x"},
	}
	for _, v := range vectors {
		got := WatchURL("http://10.0.0.7:8790", v.selector)
		want := "http://10.0.0.7:8790/#" + v.quoted
		if got != want {
			t.Errorf("WatchURL(%q) = %q, want %q", v.selector, got, want)
		}
	}
}

func TestIsAllowedMatrix(t *testing.T) {
	t.Parallel()
	cases := []struct {
		url  string
		want bool
	}{
		{"http://10.0.0.7:8790/#/srv/work/x/.hermes-lane/m", true}, // RFC1918
		{"http://127.0.0.1:8790/#/srv/work/x", true},               // loopback
		{"http://100.64.1.2:8790/#/srv/work/x", true},              // Tailscale CGNAT
		{"http://[::1]:8790/#/srv/work/x", true},                   // v6 loopback
		{"https://10.0.0.7:8790/#/srv/work/x", true},               // https ok
		{"http://10.0.0.7:8790/", true},                            // no fragment ok
		{"http://172.16.0.5:8790/#/w", true},                       // RFC1918 /12
		{"http://8.8.8.8:8790/#/srv/work/x", false},                // public host
		{"http://viewer.example.com/#/srv/work/x", false},          // bare DNS name
		{"http://[::ffff:10.0.0.7]/#/w", false},                    // v4-mapped v6 = v6 path
		{"ftp://10.0.0.7/#/srv/work/x", false},                     // scheme
		{"http://user@10.0.0.7/#/srv/work/x", false},               // userinfo
		{"http://10.0.0.7/other#/srv/work/x", false},               // path
		{"http://10.0.0.7/?q=1#/srv/work/x", false},                // query
		{"http://10.0.0.7/#", false},                               // empty fragment
		{"http://10.0.0.7/#../etc/passwd", false},                  // traversal
		{"http://10.0.0.7/#/%2e%2e/escape", false},                 // encoded traversal
		{"http://10.0.0.7/#relative/dir", false},                   // not absolute
		{"http://10.0.0.7/#/has space/dir", false},                 // raw whitespace
		{"http://10.0.0.7/#/ok%20space/dir", true},                 // escaped space ok
		{"http://10.0.0.7/#/a..b/dir", true},                       // "a.." is not traversal
		{"", false},
		{"http://10.0.0.7 /#/w", false}, // raw whitespace anywhere
	}
	for _, tc := range cases {
		if got := IsAllowed(tc.url, nil); got != tc.want {
			t.Errorf("IsAllowed(%q) = %v, want %v", tc.url, got, tc.want)
		}
	}
}

func TestIsAllowedExtraHosts(t *testing.T) {
	url := "http://viewer.lan:8790/#/srv/work/x"
	if IsAllowed(url, nil) {
		t.Error("bare DNS name must be rejected without config")
	}
	if !IsAllowed(url, []string{"viewer.lan"}) {
		t.Error("configured extra host must be accepted")
	}
	if !IsAllowed("http://VIEWER.lan/#/w", []string{"viewer.lan"}) {
		t.Error("extra host match is case-insensitive on the hostname side")
	}
}

func TestWatchURLRoundTripsThroughGate(t *testing.T) {
	// The producer's own output must always pass the gate for a private
	// base URL — a mismatch would announce links no adapter may render.
	url := WatchURL("http://100.64.0.1:8790", "/srv/work/proj with space/.hermes-lane/litellm/backend_dev")
	if !IsAllowed(url, nil) {
		t.Fatalf("produced watch URL fails its own gate: %q", url)
	}
}
